'use strict';
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
assert.equal(process.env.FOLLOW_FINAL1_PROBE_ALLOCATED, 'f352-calibration-once');
assert.equal(process.platform, 'linux');
assert.equal(process.versions.node, '24.21.0');
assert.equal(process.env.FOLLOW_CONTROL_ENGINES, 'webkit');
assert.equal(JSON.parse(fs.readFileSync(path.join(process.env.PLAYWRIGHT_MODULE, 'package.json'))).version, '1.64.1');
const filename = path.join(process.cwd(), 'scripts/validate-follow-sport-control-browser.js');
const original = fs.readFileSync(filename, 'utf8');
assert.equal(crypto.createHash('sha256').update(original).digest('hex'), '848e44ec4130eb3eac9bf5d13a632b970b5626ad23d5d98f2c48651b5f79e0c4');
const marker = "            } finally { release(); await page.unrouteAll({ behavior: 'ignoreErrors' }); await context.close(); }";
const insertion = fs.readFileSync(path.join(__dirname, 'failure-catch.js.txt'), 'utf8');
assert.equal(original.split(marker).length, 2);
const derived = original.replace(marker, insertion + marker);
assert.equal(derived.replace(insertion, ''), original);
const diagnostic = new Module(filename, module);
diagnostic.filename = filename;
diagnostic.paths = Module._nodeModulePaths(path.dirname(filename));
diagnostic._compile(derived, filename);
